function numberWords(n){n=Number(n);if(!Number.isFinite(n)||Math.abs(n)>999999999)return 'Amount out of supported range';const neg=n<0?'Minus ':'',paise=Math.round(Math.abs(n)*100),rupees=Math.floor(paise/100),cents=paise%100;const ones=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];function w(v){if(v<20)return ones[v];if(v<100)return tens[Math.floor(v/10)]+(v%10?' '+ones[v%10]:'');for(const [d,label] of [[10000000,'Crore'],[100000,'Lakh'],[1000,'Thousand'],[100,'Hundred']])if(v>=d)return w(Math.floor(v/d))+' '+label+(v%d?' '+w(v%d):'');}return neg+w(rupees)+' Rupees'+(cents?' and '+w(cents)+' Paise':'')+' Only';}
function noteGenerator(kind){const seller=esc($('noteSeller').value||'Business Name'),sellerGST=esc($('noteSellerGST').value||'—'),sellerAddress=nl($('noteSellerAddress').value||'—'),buyer=esc($('noteBuyer').value||'Customer'),buyerGST=esc($('noteBuyerGST').value||'—'),buyerAddress=nl($('noteBuyerAddress').value||'—'),no=esc($('noteNo').value||`${kind==='credit'?'CN':'DN'}-001`),date=esc($('noteDate').value||''),invoiceNo=esc($('againstInvoice').value||'—'),tax=Math.max(0,+$('noteTax').value||0),taxType=$('noteTaxType').value,items=[...document.querySelectorAll('.note-item')].map((r,i)=>({desc:r.querySelector('[data-field="desc"]')?.value||`Item ${i+1}`,hsn:r.querySelector('[data-field="hsn"]')?.value||'—',uom:r.querySelector('[data-field="uom"]')?.value||'Nos',qty:+r.querySelector('[data-field="qty"]')?.value||0,rate:+r.querySelector('[data-field="rate"]')?.value||0,discount:+r.querySelector('[data-field="discount"]')?.value||0}));let taxable=0;items.forEach(x=>taxable+=Math.max(0,x.qty*x.rate-x.discount));const gst=taxable*tax/100,cg=taxType==='intra'?gst/2:0,sg=taxType==='intra'?gst/2:0,ig=taxType==='inter'?gst:0,total=taxable+gst;const rows=items.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.desc)}</td><td>${esc(x.hsn)}</td><td>${esc(x.uom)}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${money(x.discount)}</td><td>${money(Math.max(0,x.qty*x.rate-x.discount))}</td></tr>`).join('');const title=kind==='credit'?'CREDIT NOTE':'DEBIT NOTE';msg(`<div class="invoice-paper modern"><div class="doc-banner"><div><div class="doc-title">${title}</div><div style="font-weight:800;margin-top:4px">${seller}</div><div style="white-space:pre-line;color:#4d5870">${sellerAddress}</div><div style="margin-top:4px">GSTIN: ${sellerGST}</div></div><div class="doc-meta"><b>Document No:</b> ${no}<br><b>Document Date:</b> ${date}<br><b>Against Invoice:</b> ${invoiceNo}</div></div><div class="party-grid"><div class="party-card"><b>Bill To</b>${buyer}<br><span style="white-space:pre-line">${buyerAddress}</span><br>GSTIN: ${buyerGST}</div><div class="party-card"><b>Document Purpose</b>${kind==='credit'?'Adjustment / reduction against the referenced invoice.':'Additional charge / adjustment against the referenced invoice.'}<br><span style="color:#68738a">All values are calculated from the items below.</span></div></div><table><thead><tr><th>#</th><th>Product / Service</th><th>HSN/SAC</th><th>UOM</th><th>Qty</th><th>Rate</th><th>Discount</th><th>Taxable Value</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><p>Taxable Value: <b>${money(taxable)}</b></p>${taxType==='intra'?`<p>CGST (${tax/2}%): ${money(cg)}</p><p>SGST (${tax/2}%): ${money(sg)}</p>`:`<p>IGST (${tax}%): ${money(ig)}</p>`}<div class="amount-highlight"><b>Total Value</b><strong style="float:right">${money(total)}</strong></div></div><div class="signature-grid"><span>Prepared By<br><br>________________________</span><span style="text-align:right">Authorised Signatory<br><br>________________________</span></div><p style="color:#68738a;margin-top:28px">This is a computer-generated ${kind==='credit'?'credit':'debit'} note.</p></div><div class="tool-actions"><button type="button" class="action" data-print-invoice>Print / Save PDF</button></div>`,'success');document.querySelector('[data-print-invoice]')?.addEventListener('click',e=>printOutput(e.currentTarget));addSaveDocumentButton()}
