async function resizeImage(){const f=await firstFile(),im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(Error('This image could not be decoded. Try JPG, PNG or WebP.'));im.src=localUrl(f)});const max=Number($('maxWidth').value),q=Number($('imgQuality').value);if(max<1||max>8192||q<.1||q>1)throw Error('Width must be 1–8192 pixels and quality 0.1–1.');const scale=Math.min(1,max/im.width),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));if(c.width*c.height>40000000)throw Error('Image dimensions are too large.');const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);const kind=$('outputImageFormat')?.value||'jpeg',b=await new Promise(r=>c.toBlob(r,'image/'+kind,q));if(!b)throw Error('Image output could not be created.');await showOutput(b,'yoqart-image.'+(kind==='jpeg'?'jpg':kind),'image');msg(`Image ready: ${(f.size/1024).toFixed(1)} KB → ${(b.size/1024).toFixed(1)} KB.`,'success');}
async function spreadsheetPdf(){const f=await firstFile(),wb=XLSX.read(await f.arrayBuffer(),{type:'array'});let html='<div class="invoice-paper"><h2>Spreadsheet</h2>';for(const name of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:''});if(rows.length>1000)throw Error('Preview supports up to 1,000 rows per sheet. Use Excel to PDF for a complete native conversion.');html+=`<h3>${esc(name)}</h3><table class="preview-table">`+rows.map(r=>'<tr>'+r.map(c=>`<td>${esc(c)}</td>`).join('')+'</tr>').join('')+'</table>'}html+='</div>';msg(html,'success');const b=document.createElement('button');b.textContent='Download PDF';b.className='btn';b.onclick=async()=>{try{const blob=await html2pdf().set({margin:10,html2canvas:{scale:1.5},jsPDF:{format:'a4',orientation:'landscape'}}).from($('out').querySelector('.invoice-paper')).outputPdf('blob');await showOutput(blob,'yoqart-spreadsheet.pdf','pdf')}catch(e){msg(esc(e.message),'error')}};$('out').append(b);}
