function toolGuide(t){const m=meta[t]||['','Tool','Online Tool','A practical online utility.'];const title=m[2],desc=m[3];const cat=categoryForTool(t);const categoryName=cat==='#pdf-tools'?'PDF tools':cat==='#business-tools'?'business tools':cat==='#file-tools'?'file and document tools':'social media tools';const calculator=['tds','gst','emi','percentage'].includes(t);const fileTool=cat==='#pdf-tools'||cat==='#file-tools';const steps=calculator?['Enter the values requested by the calculator.','Review the selected rate, mode or other options.','Select the calculate button to see the result.','Review the result before using it in a business, financial or compliance decision.']:fileTool?['Select the required file or files using the upload area.','Use the available preview or options to check the input and choose how it should be processed.','Run the tool and wait for the result or preview.','Review the generated output and download it when it is correct.']:['Enter the information requested by the tool.','Review the available options before running the tool.','Run the tool and check the generated result.','Download, print or use the result as appropriate.'];return `<section class="tool-guide" aria-label="About ${esc(title)}"><h2>About ${esc(title)}</h2><p>${esc(desc)} This YoqArt tool is part of the ${esc(categoryName)} collection and is designed to make a common task easier without unnecessary steps.</p><h3>How to use ${esc(title)}</h3><ol>${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>What to check before downloading</h3><p>Always review the preview or result before saving it. File conversions can behave differently with complex layouts, unusual fonts, scanned pages or unsupported features. For calculators and generated business documents, verify the inputs and final figures independently.</p><div class="guide-note"><b>Good to know:</b> YoqArt does not claim that every generated document is suitable for every legal, tax, accounting or regulatory purpose. Review important outputs before relying on them.</div><h3>Frequently asked questions</h3><p><b>Is this tool free?</b><br>YoqArt provides these online utilities without requiring a paid software installation.</p><p><b>Is there a usage limit?</b><br>PDF tools and the Invoice, Payslip, Credit Note and Debit Note generators are designed for unlimited use with no artificial daily or monthly usage counter. Normal technical limits such as file size, browser memory, processing time or server capacity may still apply.</p><p><b>Can I use the result immediately?</b><br>You can preview and download supported results, but important documents and calculations should be checked for accuracy before use.</p></section>`;}
function renderTool(t,push){clearUrls();fileRevision++;dragFiles=[];currentTool=t;const m=meta[t];if(!m)return;lastCategory=categoryForTool(t);$('categories').style.display='none';document.querySelector('.hero').style.display='none';document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$('tool-page').classList.add('active');$('toolContent').innerHTML=`<div class="tool-title">${m[1]} ${esc(m[2])}</div><p class="tool-subtitle">${esc(m[3])}</p>${(['invoice','credit-note','debit-note','payslip'].includes(t)||pdfTools.some(x=>x[0]===t))?'<div class="tool-unlimited">♾️ Unlimited use — no usage-count limit</div>':''}${body(t)}${toolGuide(t)}`;$('toolBack').href=`/${lastCategory||'#categories'}`;$('toolBack').textContent='← Back to category';if(push)history.pushState({tool:t},'',`/tools/${enc(t)}`);window.scrollTo({top:0,behavior:'smooth'});setupPicker();bindTool(t);$('toolContent').addEventListener('input',clearResult);document.querySelectorAll('#toolContent .field label').forEach(label=>{const input=label.parentElement.querySelector('input,textarea,select');if(input?.id)label.htmlFor=input.id});checkToolAvailability(t);}
function bindTool(t){if(t==='percentage'){const mode=$('pctMode'),fields=$('pctFields');const draw=()=>{fields.innerHTML=mode.value==='part'?'<div class="field"><label>Percentage</label><input id="pctPercent" type="number" value="15"></div><div class="field"><label>Base</label><input id="pctBase" type="number" value="100"></div>':mode.value==='percent'?'<div class="field"><label>Part</label><input id="pctPart" type="number" value="10"></div><div class="field"><label>Base</label><input id="pctBase" type="number" value="200"></div>':'<div class="field"><label>Part</label><input id="pctPart" type="number" value="15"></div><div class="field"><label>Percentage</label><input id="pctPercent" type="number" value="20"></div>'};mode?.addEventListener('change',draw);draw()}if(t==='invoice')bindInvoiceItemEvents();if(t==='tds'){$('tdsNotice').insertAdjacentHTML('afterend','<p>Rate-only estimate. Thresholds, PAN, eligibility and salary slabs are not evaluated. <a href="https://www.incometaxindia.gov.in/hi/w/tds-rates" target="_blank" rel="noopener noreferrer">Official TDS rates, tax year 2026–27</a> · checked 15 November 2026.</p>');const sel=$('tdsSection'),rate=$('tdsRate'),date=$('tdsDate'),act=$('tdsAct'),notice=$('tdsNotice');let lastMode=act?.value||'new';const sync=()=>{const isNew=(date?.value||'')>='2026-04-01';const mode=isNew?'new':'old';if(act)act.value=mode;if(mode!==lastMode&&sel){const previous=sel.value;sel.innerHTML=tdsOptions(mode);if([...sel.options].some(o=>o.value===previous))sel.value=previous;lastMode=mode}const r=sel?.selectedOptions[0]?.dataset.rate;if(r!==undefined&&r!=='')rate.value=r;if(notice)notice.textContent=isNew?'Payments/credits on or after 1 April 2026 use the Income-tax Act, 2025: Section 392 for salary and Section 393 table references for other TDS. Rates and monetary thresholds were largely retained.':'Payments/credits up to 31 March 2026 use the Income-tax Act, 1961 and the old TDS section numbers.'};sel?.addEventListener('change',()=>{const r=sel.selectedOptions[0]?.dataset.rate;if(r!==undefined&&r!=='')rate.value=r});date?.addEventListener('change',sync);act?.addEventListener('change',()=>{if(act.value==='new'&&date&&date.value<'2026-04-01')date.value='2026-04-01';if(act.value==='old'&&date&&date.value>='2026-04-01')date.value='2026-03-31';sync()});sync()}document.querySelectorAll('[data-run]').forEach(b=>b.addEventListener('click',async()=>{if(b.disabled)return;const r=b.dataset.run;const restore=setButtonLoading(b,actionLabel(r));const started=Date.now();try{if(!validateToolNumbers(t))return;clearResult();if(r==='office')await convert(processingUrl('/convert/'+t.replace('-to-pdf','')+'-to-pdf'),'yoqart-converted.pdf','pdf');else if(r==='unlock'){const f=await firstFile(),fd=new FormData();fd.append('file',f);fd.append('password',$('unlockPassword').value);await serverBlob(processingUrl('/unlock-pdf'),fd,'yoqart-unlocked.pdf','pdf')}else if(r==='repair')await convert(processingUrl('/repair-pdf'),'yoqart-repaired.pdf','pdf');else if(r==='merge')await merge();else if(r==='split')await split();else if(r==='remove')await split(true);else if(r==='extract')await split(false,true);else if(r==='organize')await organize();else if(r==='rotate')await rotate();else if(r==='compress')await compress();else if(r==='watermark')await watermark();else if(r==='numbers')await numberPdf();else if(r==='crop')await crop();else if(r==='edit')await annotate('edit');else if(r==='sign')await annotate('sign');else if(r==='jpgpdf')await jpgPdf();else if(r==='pdfjpg')await pdfJpg();else if(r==='word')await convert(processingUrl('/convert/pdf-to-word'),'yoqart-converted.docx','docx');else if(r==='excel')await convert(processingUrl('/convert/pdf-to-excel'),'yoqart-converted.xlsx','xlsx');else if(r==='resave'){const f=await firstFile();if(f)await makePdfDownload(await pdfDoc(f),'yoqart-resaved.pdf')}else if(r==='forms')await forms();else if(r==='protect')await protect();else if(r==='compare')await compare();else if(r==='search')await searchPdf();else if(r==='markdown')await markdown();else if(r==='summary')await summarize();else if(r==='ocr')await ocr();else if(r==='calc')calc(t);else if(r==='invoice')invoice();else if(r==='addItem')addItem();else if(r==='removeItem'){const row=b.closest('.invoice-item');if(row){const rows=document.querySelectorAll('.invoice-item');if(rows.length>1){row.remove();updateItemTaxables()}else msg('At least one item is required.','error')}}else if(r==='addNoteItem')addNoteItem();else if(r==='note')noteGenerator(t==='credit-note'?'credit':'debit');else if(r==='payslip')payslip();else if(r==='text'){textTool()}else if(r==='upper'){$('text').value=$('text').value.toUpperCase();$('text').dispatchEvent(new Event('input'))}else if(r==='lower'){$('text').value=$('text').value.toLowerCase()}else if(r==='clean'){$('text').value=$('text').value.replace(/\s+/g,' ').trim()}else if(r==='textpdf'){await textPdf()}else if(r==='image')await resizeImage();else if(r==='sheet')await spreadsheetPdf();else if(r==='media')await media();else if(r==='ppt')await pdfPpt();}catch(e){msg('⚠️ '+esc(e.message||e),'error')}finally{restore()}}));if(['document-tools','word-to-pdf','ppt-to-pdf'].includes(t))$('docText')?.addEventListener('input',()=>{(()=>{const ld=$('liveDoc');if(ld)ld.textContent=$('docText').value||'Your live document preview will appear here.'})()})}

