const resend=document.createElement('button');resend.type='button';resend.textContent='Resend verification email';resend.className='smallbtn';resend.onclick=async()=>{try{const email=$('loginEmail').value.trim();if(!email)throw Error('Enter your email above first.');resend.disabled=true;const data=await apiJson('/api/auth/resend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});authMessage(data.message,'success')}catch(e){authMessage(e.message,'error')}finally{resend.disabled=false}};$('loginPanel')?.append(resend);
