function validateToolNumbers(t){for(const input of document.querySelectorAll('#toolContent input[type=number]')){const n=Number(input.value);if(input.value===''||!Number.isFinite(n))throw Error('Enter a valid number for '+(input.labels?.[0]?.textContent||'each field')+'.');if(['invoice','credit-note','debit-note','payslip','gst','tds','emi'].includes(t)&&n<0)throw Error('Amounts and rates cannot be negative.');if((input.id.toLowerCase().includes('rate')||['tax','noteTax'].includes(input.id))&&n>100)throw Error('Tax rate must be between 0 and 100.');}return true;}
async function checkToolAvailability(t){const native=['compress-pdf','protect-pdf','pdf-to-word','pdf-to-excel','word-to-pdf','excel-to-pdf','ppt-to-pdf','unlock-pdf','repair-pdf','media-downloader'];if(!native.includes(t))return;try{const r=await fetch(processingUrl('/health'),{signal:AbortSignal.timeout(8000)});if(currentTool!==t)return;if(!r.ok){document.querySelectorAll('#toolContent [data-run]').forEach(b=>{b.disabled=true;b.textContent='Processing service unavailable'});const notice=document.createElement('div');notice.className='notice';notice.setAttribute('role','status');notice.textContent='The native processing service is currently unavailable. This tool cannot process files until it is connected. Browser-based PDF tools remain available.';$('toolContent').append(notice)}}catch{if(currentTool===t)msg('Unable to check processing service availability. Please try again shortly.','error')}}
